/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFiraCode = makeLoadFont('FiraCode');

// Load font at module level to prevent render flickering
const { fontFamily: firaCode } = loadFiraCode();



export type HackerPathProps = Record<string, any>;

const HackerPath: React.FC<HackerPathProps> = ({
  backgroundColor = "#050a05",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#00ff41",
  targetColor = "#ff003c",
  terminalHeader = "root@malloy-studio:~# ./trace_intrusion_path.sh",
  nodes = [
    "Weak login",
    "Messy session flow",
    "Abused workflow",
    "Something that actually matters",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely handle transparent backgrounds
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Typing effect for the terminal header
  const titleTypingDuration = 45;
  const charsCount = interpolate(
    frame,
    [0, titleTypingDuration],
    [0, terminalHeader.length],
    { extrapolateRight: "clamp" }
  );
  const currentHeader = terminalHeader.substring(0, Math.floor(charsCount));
  const showCursor = Math.floor(frame / 10) % 2 === 0;

  // Layout calculations
  const nodeCount = nodes.length;
  const timelineStartY = height * 0.25;
  const timelineEndY = height * 0.85;
  const timelineHeight = timelineEndY - timelineStartY;
  const gap = timelineHeight / Math.max(1, nodeCount - 1);

  // Dynamic timing based on duration and node count
  const totalFrames = durationInSeconds * fps;
  const sequenceEndFrame = totalFrames * 0.85; // Finish animation before the very end
  const framesPerStep = (sequenceEndFrame - titleTypingDuration) / Math.max(1, nodeCount);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: firaCode,
        color: accentColor,
      }}
    >
      {/* Scanline Overlay */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background:
            "repeating-linear-gradient(0deg, rgba(0,0,0,0.15), rgba(0,0,0,0.15) 2px, transparent 2px, transparent 4px)",
          pointerEvents: "none",
          zIndex: 100,
        }}
      />

      {/* Terminal Header */}
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: width * 0.1,
          fontSize: 32,
          fontWeight: "bold",
          opacity: 0.9,
          maxWidth: width * 0.8,
          wordBreak: "break-all",
        }}
      >
        {currentHeader}
        <span style={{ opacity: showCursor ? 1 : 0 }}>_</span>
      </div>

      {/* Lines connecting nodes */}
      {nodes.map((_, i) => {
        if (i === nodeCount - 1) return null; // No line after the last node

        const nodeStartFrame = titleTypingDuration + i * framesPerStep;
        const lineStartFrame = nodeStartFrame + framesPerStep * 0.3;
        const lineDrawDuration = framesPerStep * 0.6;

        const lineDraw = interpolate(
          frame,
          [lineStartFrame, lineStartFrame + lineDrawDuration],
          [0, gap],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );

        return (
          <div
            key={`line-${i}`}
            style={{
              position: "absolute",
              left: width * 0.15 - 2, // Centered on the 40px node (width 4, offset 2)
              top: timelineStartY + i * gap,
              width: 4,
              height: lineDraw,
              backgroundColor: accentColor,
              opacity: 0.6,
            }}
          />
        );
      })}

      {/* Nodes */}
      {nodes.map((nodeText, i) => {
        const isTarget = i === nodeCount - 1;
        const nodeStartFrame = titleTypingDuration + i * framesPerStep;

        const scale = spring({
          fps,
          frame: frame - nodeStartFrame,
          config: { damping: 12, stiffness: 100 },
        });

        const textOpacity = interpolate(
          frame,
          [nodeStartFrame + 5, nodeStartFrame + 15],
          [0, 1],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );

        const textTranslateX = interpolate(
          frame,
          [nodeStartFrame + 5, nodeStartFrame + 25],
          [-20, 0],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );

        const colorToUse = isTarget ? targetColor : accentColor;

        return (
          <div
            key={`node-${i}`}
            style={{
              position: "absolute",
              left: width * 0.15,
              top: timelineStartY + i * gap,
              transform: `translate(-50%, -50%)`,
            }}
          >
            {/* Node Circle */}
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: 20,
                backgroundColor: isTarget ? targetColor : backgroundColor,
                border: `4px solid ${colorToUse}`,
                transform: `scale(${scale})`,
                boxShadow: isTarget && scale > 0 ? `0 0 30px ${targetColor}` : "none",
                position: "absolute",
                top: -20,
                left: -20,
                zIndex: 10,
              }}
            />

            {/* Node Text */}
            <div
              style={{
                position: "absolute",
                left: 50, // Offset from the center of the circle
                top: -24, // Vertically align with circle roughly
                color: colorToUse,
                fontSize: isTarget ? 48 : 40,
                fontWeight: isTarget ? "bold" : "normal",
                whiteSpace: "normal",
                wordBreak: "break-word",
                width: width * 0.7, // Allow wrapping for long text
                lineHeight: 1.2,
                opacity: textOpacity,
                transform: `translateX(${textTranslateX}px)`,
                textShadow: isTarget ? `0 0 20px ${targetColor}` : "none",
              }}
            >
              {nodeText}
            </div>
          </div>
        );
      })}

      {/* Final Alert Overlay (Appears after sequence) */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.05,
          left: width * 0.1,
          width: width * 0.8,
          fontSize: 28,
          color: targetColor,
          fontWeight: "bold",
          opacity: interpolate(
            frame,
            [sequenceEndFrame, sequenceEndFrame + 15],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          ),
          textShadow: `0 0 10px ${targetColor}`,
        }}
      >
        [!] TARGET ACCESSED
      </div>
    </AbsoluteFill>
  );
};

export default HackerPath;